mapper.select:
select c.content,ifnull(u.user_name,'神秘用户') as nickName,u.avatar as imageUrl,c.create_time as createTime,c.comment_id as commentId, u.phone,ifnull(u2.user_name,'神秘用户') as byNickName,u2.avatar as byImageUrl,u.user_id as userId,c.good_num as goodNum,u.province,is_recommend as isRecommend, (select count(*) from good_comment cc where cc.comment_id=c.comment_id) as goodCount,c.content_img as contentImg,c.user_id_str as userIdStr, (select count(*) from talk_comment cc where cc.parent_id=c.comment_id) as counts,c.is_delete as isDelete from talk_comment c left join tb_user u on u.user_id=c.user_id left join tb_user u2 on u2.user_id=c.by_user_id where u.user_id is not null
and c.parent_id=#{parentId}
and c.user_id=#{userId}
and c.talk_id=#{talkId}
and u.user_name like concat('%',#{userName},'%')
and u.phone like concat('%',#{phone},'%')
and c.content like concat('%',#{content},'%')
order by c.create_time desc
